print(len(blocks), len(set(blocks)))

# verify STS(13): every pair exactly once
from collections import Counter
pairs = Counter()
for b in blocks:
    for i in range(3):
        for j in range(i+1,3):
            pairs[(b[i],b[j])] += 1
print(len(pairs), min(pairs.values()), max(pairs.values()))
